mapper.update:
UPDATE CHAT_PRTPNT
   SET PTCP_STTS_CD = #{ptcpSttsCd}
     , MDFCN_DT = NOW()
 WHERE OTO_CHAT_ROOM_SN = #{otoChatRoomSn}
   AND MBR_SN = #{mbrSn}

mapper.select:
SELECT T.MBR_SN
  FROM CHAT_PRTPNT T
 WHERE T.OTO_CHAT_ROOM_SN = #{otoChatRoomSn}
   AND T.PTCP_STTS_CD = #{joinedCd}

SELECT C.OTO_CHAT_ROOM_SN
  FROM OTO_CHAT_ROOM C
 WHERE C.PST_SN = #{pstSn}
   AND C.OTO_CHAT_ROOM_SN <> #{exceptRoomSn}
 ORDER BY C.OTO_CHAT_ROOM_SN

SELECT C.OTO_CHAT_ROOM_SN , C.CHAT_ROOM_STTS_CD , C.PST_SN , P.PST_TTL , CASE WHEN P.MBR_SN = #{mbrSn} THEN C.CTPT_MBR_SN ELSE P.MBR_SN END AS CTPT_MBR_SN , CASE WHEN P.MBR_SN = #{mbrSn} THEN ELSE END AS CTPT_MBR_NCNM , CASE WHEN P.MBR_SN = #{mbrSn} THEN ELSE END AS CTPT_ATCH_FILE_SN , CASE WHEN P.MBR_SN = #{mbrSn} THEN #{guardianRole} ELSE #{sitterRole} END AS MY_ROLE , T.MTCH_DLNG_STTS_CD , LM.MSG_TYPE_CD AS LAST_MSG_TYPE_CD , LM.MSG_CN_ENC AS LAST_MSG_CN_ENC , LM.REG_DT AS LAST_MSG_DT , ( SELECT COUNT(*) FROM CHAT_MSG UM WHERE UM.OTO_CHAT_ROOM_SN = C.OTO_CHAT_ROOM_SN AND UM.MSG_SEQ > ME.LAST_PRSL_MSG_SEQ AND UM.MBR_SN IS NOT NULL AND UM.MBR_SN <> #{mbrSn} ) AS UNREAD_CNT FROM OTO_CHAT_ROOM C JOIN CHAT_PRTPNT ME ON ME.OTO_CHAT_ROOM_SN = C.OTO_CHAT_ROOM_SN AND ME.MBR_SN = #{mbrSn} AND ME.PTCP_STTS_CD = #{joinedCd} JOIN PST P ON P.PST_SN = C.PST_SN JOIN MBR O ON O.MBR_SN = P.MBR_SN JOIN MBR A ON A.MBR_SN = C.CTPT_MBR_SN LEFT JOIN PET_PRTC_MTCH T ON T.OTO_CHAT_ROOM_SN = C.OTO_CHAT_ROOM_SN LEFT JOIN CHAT_MSG LM ON LM.OTO_CHAT_ROOM_SN = C.OTO_CHAT_ROOM_SN AND LM.MSG_SEQ = ( SELECT MAX(M2.MSG_SEQ) FROM CHAT_MSG M2 WHERE M2.OTO_CHAT_ROOM_SN = C.OTO_CHAT_ROOM_SN ) WHERE 1 = 1
AND P.MBR_SN = #{mbrSn}
AND C.CTPT_MBR_SN = #{mbrSn}
AND C.PST_SN = #{cond.pstSn}
AND EXISTS ( SELECT 1 FROM CHAT_MSG UM2 WHERE UM2.OTO_CHAT_ROOM_SN = C.OTO_CHAT_ROOM_SN AND UM2.MSG_SEQ > ME.LAST_PRSL_MSG_SEQ AND UM2.MBR_SN IS NOT NULL AND UM2.MBR_SN <> #{mbrSn} )
ORDER BY COALESCE(LM.REG_DT, C.REG_DT) DESC , C.OTO_CHAT_ROOM_SN DESC

SELECT COUNT(*)
  FROM CHAT_MSG UM
  JOIN CHAT_PRTPNT ME
    ON ME.OTO_CHAT_ROOM_SN = UM.OTO_CHAT_ROOM_SN
   AND ME.MBR_SN = #{mbrSn}
   AND ME.PTCP_STTS_CD = #{joinedCd}
 WHERE UM.MSG_SEQ > ME.LAST_PRSL_MSG_SEQ
   AND UM.MBR_SN IS NOT NULL
   AND UM.MBR_SN <> #{mbrSn}
